# owner: platform
"""Lay students out in seating rows, one line of text per row."""

from typing import List
from rosterkit.models import Student

def _check_layout(students: List[Student], seats_per_row: int) -> None:
    """Refuse layouts that cannot seat anyone."""
    if seats_per_row <= 0:
        raise ValueError(f"seats per row must be positive: {seats_per_row}")
    if not students:
        raise ValueError("no students to seat")

def _name_key(student: Student) -> tuple[str, str]:
    """Last name first, ignoring case, with first name as the tie-break."""
    return (student.last_name.casefold(), student.first_name.casefold())

def _row_text(number: int, seated: List[Student]) -> str:
    names = " | ".join(student.display_name for student in seated)
    return f"Row {number}: {names}"

# ---
def seat_rows(students: List[Student], seats_per_row: int) -> List[str]:
    """One line of text per seating row, students ordered by last name."""
    _check_layout(students, seats_per_row)
    ordered = sorted(students, key=_name_key)
    return [
        _row_text(start // seats_per_row + 1, ordered[start:start + seats_per_row])
        for start in range(0, len(ordered), seats_per_row)
    ]

