# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def make_student(student_id: str, last_name: str, first_name: str) -> Student:
    return Student(student_id, last_name, first_name, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("1", "Halloway", "Juno"),
            make_student("2", "Dunmere", "Piet"),
            make_student("3", "Okonkwo", "Ada"),
            make_student("4", "Brandt", "Lio"),
            make_student("5", "Varrow", "Ines")
        ]

    def test_rows_hold_the_given_number_of_seats(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(len(lines), 3)

    def test_row_text_lists_names_in_last_name_order(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(lines[0], "Row 1: Brandt, Lio | Dunmere, Piet")
        self.assertEqual(lines[1], "Row 2: Halloway, Juno | Okonkwo, Ada")
        self.assertEqual(lines[2], "Row 3: Varrow, Ines")

    def test_last_name_order_ignores_case(self):
        students = [
            make_student("1", "dunmere", "Piet"),
            make_student("2", "Brandt", "Lio")
        ]
        lines = seat_rows(students, 5)
        self.assertEqual(lines, ["Row 1: Brandt, Lio | dunmere, Piet"])

    def test_first_name_breaks_ties_in_last_name(self):
        students = [
            make_student("1", "Lane", "Zoe"),
            make_student("2", "Lane", "Amos")
        ]
        lines = seat_rows(students, 2)
        self.assertEqual(lines, ["Row 1: Lane, Amos | Lane, Zoe"])

    def test_input_list_is_not_reordered(self):
        seat_rows(self.students, 2)
        self.assertEqual(self.students[0].student_id, "1")

    def test_one_row_when_every_seat_fits(self):
        lines = seat_rows(self.students, 10)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("Row 1: Brandt, Lio"))

    def test_zero_seats_per_row_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_per_row_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -3)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
